<?php

namespace App\Filament\Resources\SeoOpportunities;

use App\Filament\Resources\SeoOpportunities\Pages\ManageSeoOpportunities;
use App\Filament\Resources\SeoOpportunities\Tables\SeoOpportunitiesTable;
use App\Models\SeoOpportunity;
use BackedEnum;
use Filament\Resources\Resource;
use Filament\Schemas\Schema;
use Filament\Support\Icons\Heroicon;
use Filament\Tables\Table;

/**
 * Fully system-generated by App\Domain\Seo\OpportunityEngine - there is no
 * create/edit form here on purpose, only a review workflow (see
 * SeoOpportunitiesTable's row actions).
 */
class SeoOpportunityResource extends Resource
{
    protected static ?string $model = SeoOpportunity::class;

    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedLightBulb;

    protected static string|\UnitEnum|null $navigationGroup = 'مرکز سئو';

    protected static ?string $navigationLabel = 'فرصت‌های سئو';

    protected static ?string $modelLabel = 'فرصت سئو';

    protected static ?string $pluralModelLabel = 'فرصت‌های سئو';

    protected static ?string $recordTitleAttribute = 'title';

    public static function form(Schema $schema): Schema
    {
        return $schema->components([]);
    }

    public static function table(Table $table): Table
    {
        return SeoOpportunitiesTable::configure($table);
    }

    public static function getPages(): array
    {
        return [
            'index' => ManageSeoOpportunities::route('/'),
        ];
    }
}
